#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, k;
    cin >> n >> k;

    vector<int> a(n);
    for (int &x : a) cin >> x;

    int ans = 0;
    int left = 0;

    while (left < n && a[left] <= k) {
        ++ans;
        ++left;
    }

    int right = n - 1;
    while (right >= left && a[right] <= k) {
        ++ans;
        --right;
    }

    cout << ans;
    return 0;
}

